import{_ as i,o as a,c as e,al as t}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"Sanitizers","description":"","frontmatter":{},"headers":[],"relativePath":"ko/test_and_ci/sanitizers.md","filePath":"ko/test_and_ci/sanitizers.md"}'),n={name:"ko/test_and_ci/sanitizers.md"};function r(l,s,o,d,h,p){return a(),e("div",null,[...s[0]||(s[0]=[t('<h1 id="sanitizers" tabindex="-1">Sanitizers <a class="header-anchor" href="#sanitizers" aria-label="Permalink to &quot;Sanitizers&quot;">​</a></h1><p><a href="https://github.com/google/sanitizers" target="_blank" rel="noreferrer">Sanitizers</a> are compiler-instrumentation tools that detect whole classes of bugs at runtime. PX4 can build <a href="./../simulation/">SITL</a> with them to catch problems that are otherwise hard to reproduce:</p><ul><li><strong>AddressSanitizer (ASan)</strong> — out-of-bounds accesses, use-after-free, memory leaks.</li><li><strong>ThreadSanitizer (TSan)</strong> — data races and lock-order inversions.</li><li><strong>MemorySanitizer (MSan)</strong> — reads of uninitialized memory (Clang only).</li><li><strong>UndefinedBehaviorSanitizer (UBSan)</strong> — undefined behaviour (signed overflow, misaligned access, …).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Sanitizers are only available for POSIX/SITL builds, where the host compiler instruments the code. They are not used on the NuttX flight-controller targets.</p></div><h2 id="building-and-running" tabindex="-1">Building and running <a class="header-anchor" href="#building-and-running" aria-label="Permalink to &quot;Building and running&quot;">​</a></h2><p>Set the matching environment variable when building SITL. It selects the corresponding <code>CMAKE_BUILD_TYPE</code>:</p><table tabindex="0"><thead><tr><th>변수</th><th>Sanitizer</th></tr></thead><tbody><tr><td><code>PX4_ASAN</code></td><td>AddressSanitizer</td></tr><tr><td><code>PX4_TSAN</code></td><td>ThreadSanitizer</td></tr><tr><td><code>PX4_MSAN</code></td><td>MemorySanitizer</td></tr><tr><td><code>PX4_UBSAN</code></td><td>UndefinedBehaviorSanitizer</td></tr></tbody></table><p>For example, to build and run SITL under ThreadSanitizer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_TSAN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_default</span></span></code></pre></div><p>To build and run the unit and integration test suite under a sanitizer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_TSAN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A sanitizer is a distinct <code>CMAKE_BUILD_TYPE</code>, so switching to or from one rebuilds from scratch. Sanitized binaries are larger and run several times slower (ASan/TSan roughly 2–5×), and lockstep timing changes, so expect tests to take longer.</p></div><h2 id="linux-aslr-fix" tabindex="-1">Linux: ASLR fix <a class="header-anchor" href="#linux-aslr-fix" aria-label="Permalink to &quot;Linux: ASLR fix&quot;">​</a></h2><p>On recent Linux kernels the default address-space-layout randomization entropy is too high for the sanitizer runtimes&#39; shadow-memory mapping, and the process aborts at startup with e.g.:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FATAL: ThreadSanitizer: unexpected memory mapping 0x... - 0x...</span></span></code></pre></div><p>Lower the mmap randomization (needed for both ASan and TSan), once per boot:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sysctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm.mmap_rnd_bits=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">28</span></span></code></pre></div><p>To make it persistent across reboots:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;vm.mmap_rnd_bits=28&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tee</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /etc/sysctl.d/99-sanitizers.conf</span></span></code></pre></div><p>If <code>28</code> still fails on your kernel, try <code>26</code>.</p><h2 id="threadsanitizer-suppressions" tabindex="-1">ThreadSanitizer suppressions <a class="header-anchor" href="#threadsanitizer-suppressions" aria-label="Permalink to &quot;ThreadSanitizer suppressions&quot;">​</a></h2><p>Running SITL with the Gazebo bridge under TSan reports many data races inside the third-party simulation transport (ZeroMQ and gz-transport) and the PX4↔Gazebo bridge glue. None of this is in the flight code path or the SIH-based CI, and it can&#39;t be fixed here, so it is filtered with a suppressions file at <code>test/sitl_tsan.supp</code>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TSAN_OPTIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;suppressions=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/test/sitl_tsan.supp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_TSAN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gz_x500</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Only add third-party / simulation symbols to the suppressions file — never flight-code symbols. A race detector is only useful at zero reports; suppressing your own code blinds it to real bugs.</p></div>',24)])])}const u=i(n,[["render",r]]);export{k as __pageData,u as default};
